mapper.select:
SELECT public > 0 AS publicProblem, showsolution > 0 AS showSolution, caseAmount
FROM problem
WHERE name = #{name}

mapper.update:
UPDATE problem
SET caseAmount = caseAmount + 1
WHERE name = #{name}

mapper.select:
SELECT name, cnname, tags, difficulty, 0 AS accepted
FROM problem
WHERE public = 1
ORDER BY ${order}
LIMIT #{start}, #{limit}

